functions.routeByOrigin:
function routeByOrigin(p) {
  var origem   = String(p.origem || '').trim().toLowerCase();
  var temNome  = !!(p.nome && String(p.nome).trim());
  var temWhats = !!(p.telefone || p.telefone_digits || p.whatsapp);

  if (origem.indexOf('bolsao') === 0) return handleBolsao(p); // bolsao_lp e variantes

  if (origem.indexOf('dicionario_') === 0 || origem === 'lead_magnet_dicionario') {
    return handleDicionario(p);
  }
  var newsletterOrigins = ['exit_intent', 'sticky_bar', 'blog_newsletter', 'newsletter'];
  if (newsletterOrigins.indexOf(origem) >= 0) return handleNewsletter(p);

  var listaOrigins = ['blog_inline_cta', 'lista_espera', 'site_lista_espera'];
  if (listaOrigins.indexOf(origem) >= 0) return handleLista(p);

  // ⚠️ ORDEM CRÍTICA: este teste vem ANTES do de `lives_form`. Se alguma peça
  // antiga ainda mandar `lives_form_sefaz_sc`, ela cai aqui e NÃO na sequência
  // das 4 lives de agosto (que é o que o handleLives dispara).
  if (origem.indexOf('aula_') === 0 || origem === 'lives_form_sefaz_sc') {
    return handleAulaAoVivo(p);
  }

  if (origem.indexOf('lives_form') === 0) return handleLives(p);

  if (temNome || temWhats) return handleLista(p);
  return handleNewsletter(p);
}

functions.leadHeaders_:
function leadHeaders_(sheet, required, allColumns) {
  if (!sheet) throw new Error('CAPTURA_ABA_AUSENTE');
  var ss = SpreadsheetApp.getActiveSpreadsheet(), id = ss.getId();
  var width = sheet.getLastColumn();
  if (width < 1 || width > 200) throw new Error('CAPTURA_CABECALHO_INVALIDO');
  var range = {
    sheetId: sheet.getSheetId(), startRowIndex: 0, endRowIndex: 1, startColumnIndex: 0, endColumnIndex: width
  };
  if (allColumns) delete range.endColumnIndex; // preparo: não depende do cache de largura do SpreadsheetApp
  var res = Sheets.Spreadsheets.getByDataFilter({ includeGridData: true, dataFilters: [{ gridRange: range }] }, id);
  if (!res || res.spreadsheetId !== id) throw new Error('CAPTURA_PLANILHA_DIVERGENTE');
  var found = (res.sheets || []).filter(function(s) { return s.properties && s.properties.sheetId === sheet.getSheetId(); });
  if (found.length !== 1 || found[0].properties.title !== sheet.getName()) throw new Error('CAPTURA_ABA_DIVERGENTE');
  if (allColumns) {
    width = found[0].properties.gridProperties && found[0].properties.gridProperties.columnCount;
    if (!Number.isInteger(width) || width < 1 || width > 200) throw new Error('CAPTURA_GRADE_FORA_LIMITE');
  }
  var headers = new Array(width).fill(''), cols = Object.create(null);
  (found[0].data || []).forEach(function(d) {
    if ((d.startRow || 0) !== 0) return;
    var cells = d.rowData && d.rowData[0] && d.rowData[0].values || [];
    cells.forEach(function(cell, i) {
      var u = cell.userEnteredValue || {}, e = cell.effectiveValue || {}, col = (d.startColumn || 0) + i;
      if (col >= width || (u.stringValue === undefined && u.formulaValue === undefined)) return;
      if (u.formulaValue !== undefined || typeof u.stringValue !== 'string' || e.stringValue !== u.stringValue)
        throw new Error('CAPTURA_CABECALHO_NAO_LITERAL');
      var h = u.stringValue;
      if (!h) return;
      if (cols[h]) throw new Error('CAPTURA_CABECALHO_DUPLICADO');
      headers[col] = h; cols[h] = col + 1;
    });
  });
  (required || []).forEach(function(h) { if (!cols[h]) throw new Error('CAPTURA_COLUNA_AUSENTE:' + h); });
  return { headers: headers, cols: cols, width: width, sheetId: sheet.getSheetId(), spreadsheetId: id };
}

functions.handleAulaAoVivo:
function handleAulaAoVivo(p) {
  var origem = String(p.origem || '').trim().toLowerCase();

  // `lives_form_sefaz_sc` é aceito por compatibilidade com peça antiga.
  var cfg = aulasCfgPorOrigem_(origem)
         || (origem === 'lives_form_sefaz_sc' ? aulasCfgPorOrigem_('aula_sefaz_sc') : null);

  // Origem `aula_*` desconhecida NÃO vira lead órfão: registra o erro e usa um
  // rótulo explícito, para aparecer na planilha em vez de sumir.
  if (!cfg) {
    logError('Aula ao vivo: origem não configurada', { parameter: {} });
    cfg = { campanha: 'DESCONHECIDA (' + origem + ')', topico: 'aula-outras' };
  }

  var email = String(p.email || '').trim().toLowerCase();
  var nome = String(p.nome || '').trim();
  var telefone = normalizePhone(p.telefone_digits || p.telefone || p.whatsapp || '');
  var now = new Date();

  appendLeadByHeader_(SHEETS.AULAS, AULAS_HEADERS, [
    now, cfg.campanha, nome, email, telefone,
    origem, String(p.ref || ''),
    String(p.pagina || ''), String(p.referrer || ''),
    String(p.utm_source || ''), String(p.utm_medium || ''), String(p.utm_campaign || ''),
    String(p.dispositivo || ''),
    'off', '',     // CRM Sync: desligado até o template do Mensageiro existir
    '', ''         // SES Sync: pendente para o trabalhador de contatos
  ]);

  return jsonResponse({ ok: true, aba: SHEETS.AULAS, campanha: cfg.campanha });
}
